"""Static shell based on the user's hash-verified 19 November layout; no I/O."""
CSS = '''
:root{--bg-0:#0c1219;--bg-1:#111a24;--bg-2:#182430;--bg-3:#1e2d3d;--border:#2a3a4d;--text-0:#e8edf4;--text-1:#b0c0d0;--text-2:#8296aa;--cyan:#4dd0e1;--amber:#ffa726;color-scheme:dark;font-family:system-ui,sans-serif;font-size:14px}
*{box-sizing:border-box}body{margin:0;background:var(--bg-0);color:var(--text-1);line-height:1.6}button,input,textarea,select{font:inherit}button,a,input,textarea,select,summary{outline-offset:3px}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid var(--cyan)}a{color:var(--cyan)}button{cursor:pointer;background:var(--bg-2);border:1px solid var(--border);border-radius:5px;color:var(--text-1);padding:8px 12px}button:hover{border-color:var(--cyan);color:var(--text-0)}button:disabled{opacity:.55;cursor:not-allowed}.primary{background:#163b46;color:var(--cyan);border-color:#286374}.hdr{height:48px;display:flex;align-items:center;gap:12px;padding:0 16px;background:var(--bg-1);border-bottom:1px solid var(--border)}.brand{color:var(--text-0);font-weight:700;letter-spacing:1px;white-space:nowrap}.brand-icon{display:inline-grid;place-items:center;width:28px;height:28px;border:1px solid #2e6673;background:#163b46;border-radius:6px;color:var(--cyan);margin-right:9px}.hdr-sep{height:22px;width:1px;background:var(--border)}.crumb{font-size:13px;color:var(--text-2)}.tag{font-size:11px;border:1px solid var(--border);padding:2px 7px;border-radius:4px;color:var(--text-2)}.hdr .tag{margin-left:auto;white-space:nowrap}.layout{display:grid;grid-template-columns:240px minmax(0,1fr) 380px;height:calc(100dvh - 48px);min-height:480px}.side{background:var(--bg-1);border-right:1px solid var(--border);padding:20px 14px;overflow:auto;min-width:0}.side-label,.eyebrow{font-size:11px;letter-spacing:1.5px;color:var(--text-2);text-transform:uppercase}.side h2{font-size:16px;color:var(--text-0);margin:6px 0 16px}.side p{font-size:12px;overflow-wrap:anywhere}.side #refresh{width:100%}#cases{display:grid;gap:8px;margin-top:18px}#cases button{text-align:left;border-left:2px solid transparent;padding:14px 10px;overflow-wrap:anywhere}#cases button[aria-pressed=true]{border-left-color:var(--cyan);background:#1a303d;color:var(--text-0)}.main{min-width:0;display:flex;flex-direction:column;overflow:hidden}.stage-bar{height:46px;flex-shrink:0;display:flex;align-items:stretch;padding:0 12px;border-bottom:1px solid var(--border);background:var(--bg-1);overflow-x:auto}.stage-bar ol{display:flex;list-style:none;padding:0;margin:0;width:100%;min-width:520px;justify-content:space-between;gap:2px}.stage-bar li{display:flex;align-items:center;gap:6px;white-space:nowrap;font-size:12px;padding:0 6px;border-bottom:2px solid transparent;color:var(--text-2)}.stage-bar a{text-decoration:none;color:inherit}.stage-bar .active{color:var(--cyan);border-color:var(--cyan);background:var(--bg-2)}.stage-num{border:1px solid var(--border);border-radius:50%;width:21px;height:21px;display:inline-grid;place-items:center;font-size:10px;font-family:monospace}.active .stage-num{background:var(--cyan);color:var(--bg-0);border-color:var(--cyan)}.content-main{overflow:auto;padding:24px;min-width:0;flex:1}.page-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:22px}.page-heading h1{font-size:23px;color:var(--text-0);margin:3px 0 5px}.page-heading p{margin:0;font-size:12px;color:var(--text-2)}.card{border:1px solid var(--border);border-radius:7px;background:var(--bg-1);margin-bottom:18px;overflow:hidden}.card-head{padding:13px 16px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;gap:12px}.card-head h2{margin:0;font-size:14px;font-weight:600;color:var(--text-0)}.card-body{padding:16px}.card-body p:first-child{margin-top:0}.empty{padding:34px 22px;text-align:center;color:var(--text-2)}.empty-mark{font-family:monospace;font-size:26px;color:#426273;margin-bottom:10px}.empty h3{font-size:16px;color:var(--text-1);font-weight:500;margin:0 0 7px}.empty p{font-size:12px;max-width:380px;margin:0 auto}.evidence-row{display:grid;grid-template-columns:36px minmax(0,1fr) auto;gap:12px;align-items:center;padding:16px;border-bottom:1px solid var(--border)}.evidence-row:last-child{border:0}.file-icon{width:34px;height:40px;display:grid;place-items:center;border:1px solid #355164;border-radius:5px;color:var(--cyan);font-size:10px;font-family:monospace}.evidence-row h3{margin:0;font-size:13px;color:var(--text-0)}.evidence-row p{margin:3px 0 0;font-size:12px;color:var(--text-2)}.muted{color:var(--text-2)}.inspector{background:var(--bg-1);border-left:1px solid var(--border);padding:20px;overflow:auto;min-width:0}.inspector h2{font-size:15px;color:var(--text-0);margin:0 0 20px}.inspect-block{border-bottom:1px solid var(--border);padding:0 0 20px;margin:0 0 20px}.inspect-block h3{font-size:12px;color:var(--text-2);font-weight:500;margin:0 0 10px}.inspect-block p{font-size:13px;margin:5px 0;overflow-wrap:anywhere}.notice{font-size:12px;color:#d3b682;background:#24231f;border:1px solid #4a402f;border-radius:5px;padding:12px;overflow-wrap:anywhere}.steps{list-style:none;padding:0;margin:0;counter-reset:step}.steps li{font-size:12px;padding:9px 0;display:flex;gap:10px}.steps li:before{counter-increment:step;content:counter(step);color:var(--cyan);font-family:monospace}#source:empty:before{content:"尚未载入来源声明";color:var(--text-2);font-size:12px}.inspector pre{font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere;margin:0}.inspector #case-title{font-size:16px;color:var(--text-0);margin-top:8px}#image-entry:empty{display:none}#image-entry{padding:16px;border-top:1px solid var(--border)}#image-entry a{display:block;padding:10px 12px;border:1px solid #286374;background:#163b46;border-radius:5px;text-decoration:none;font-size:13px}#return-hint{font-size:12px}.side label{display:block;font-size:12px;margin:10px 0}.side input{width:100%;min-width:0}.side button{max-width:100%;white-space:normal}.side pre{font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere}input,textarea,select{background:var(--bg-0);color:var(--text-0);border:1px solid var(--border);border-radius:4px;padding:8px;max-width:100%}textarea{width:100%;min-height:86px;resize:vertical}details{border:1px solid var(--border);background:var(--bg-1);border-radius:6px;margin-bottom:18px;padding:0 16px 14px}summary{cursor:pointer;color:var(--text-1);font-size:13px;padding:13px 0}details:not([open]){padding-bottom:0}details label{display:block;margin:12px 0;font-size:12px}details input:not([type=checkbox]){width:100%}details p{font-size:12px;color:var(--text-2)}.review-grid{display:block}.review-grid [hidden]{display:none!important}#lines article{padding:16px;margin-bottom:16px;border:1px solid var(--border);border-radius:7px;background:var(--bg-1)}#lines article>p{font-size:13px;color:var(--text-1)}#lines article select,#lines article input{display:block;width:100%;margin:10px 0}#lines article button{margin:8px 0}#lines article pre{font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere;color:var(--text-2)}#lines:empty:before{content:'尚未载入核对内容。请主动列出已有记录，或展开下方入口导入已登记结果。';display:block;padding:42px 20px;text-align:center;border:1px dashed var(--border);border-radius:7px;font-size:13px;color:var(--text-2)}#run-options button{display:block;width:100%;margin:8px 0;text-align:left;overflow-wrap:anywhere}.status-stack p:empty{display:none}.status-stack{font-size:12px;overflow-wrap:anywhere;margin-bottom:16px}[hidden]{display:none!important}@media(max-width:1190px){.layout{grid-template-columns:220px minmax(0,1fr) 300px}.content-main{padding:18px}.inspector{padding:16px}}@media(max-width:980px){.layout{grid-template-columns:220px minmax(0,1fr);height:auto;min-height:calc(100dvh - 48px)}.inspector{grid-column:2;border-top:1px solid var(--border)}.main{overflow:visible}.content-main{overflow:visible}.side{grid-row:1 / span 2}}@media(max-width:640px){.hdr{padding:0 10px;gap:8px}.crumb{display:none}.layout{display:block}.side{max-height:320px;border-right:0;border-bottom:1px solid var(--border)}.inspector{border-left:0}.content-main{padding:16px}.page-heading h1{font-size:21px}.stage-bar{padding:0 8px}.evidence-row{grid-template-columns:32px minmax(0,1fr)}.evidence-row .tag{grid-column:2}.page-heading .tag{display:none}}
'''
HEADER = '<header class="hdr"><div class="brand"><span class="brand-icon" aria-hidden="true">航</span>粤海探析</div><span class="hdr-sep"></span><div class="crumb">调查工作台 <span aria-hidden="true"> / </span> 取证</div><span class="tag">合成试用 · 未运行验收</span></header>'
STAGES = '<nav class="stage-bar" aria-label="案件流程（位置不代表完成）"><ol>'+''.join('<li'+(' class="active"' if i==2 else '')+'><span class="stage-num">'+str(i)+'</span>'+title+'</li>' for i,title in enumerate(['接报','取证','询问','分析','报告','建议','沉淀'],1))+'</ol></nav>'


def image_shell(html):
    """Rearrange only fixed static markup; preserve the actual inline JS verbatim."""
    def split_once(text, marker):
        if text.count(marker) != 1:
            raise ValueError('pilot evidence shell marker mismatch')
        return text.split(marker, 1)
    before, scripts = split_once(html, '<script src=')
    _, body = split_once(before, '<label>案件ID')
    queue, body = split_once('<label>案件ID'+body, '<details><summary>导入已登记结果</summary>')
    if body.count('</details>') != 2:
        raise ValueError('pilot evidence import/task grouping mismatch')
    imports, body = body.split('</details>',1)
    tasks, content = split_once(body, '<p id="reopen-address"')
    content = '<p id="reopen-address"'+content
    for marker in ('<p id="loaded-context" role="status"></p>', '<div id="source"></div>', '<button id="pilot-return" type="button" hidden>返回取证工作台（提示回选本案）</button>'):
        if content.count(marker) != 1:
            raise ValueError('pilot evidence context marker mismatch')
        content=content.replace(marker,'')
    return ('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>粤海探析 · 图片核对</title><style>'+CSS+'</style><body>'+HEADER+
        '<div class="layout"><aside class="side" aria-label="当前案与核对记录"><div class="side-label">CASE WORKSPACE</div><h2>案件与核对记录</h2><a href="/pilot">返回授权案件队列</a><p class="muted">离页仍保留原有未保存草稿确认。</p><button id="pilot-return" type="button" hidden>返回取证工作台（提示回选本案）</button>'+queue+'</aside>'+
        '<main class="main">'+STAGES+'<div class="content-main"><div class="page-heading"><div><div class="eyebrow">EVIDENCE / REVIEW</div><h1>图片文字核对</h1><p>已保存记录 → 内容核对 → 追加人工修订</p></div><span class="tag">当前运行 · 非报告历史</span></div><div class="status-stack">'+content+'</div><details><summary>＋ 导入已登记结果 · 四份请求摘要</summary>'+imports+'</details>'+tasks+'</div></main>'+
        '<aside class="inspector" aria-label="来源、版本与待核对事项"><h2>来源与核对上下文</h2><section class="inspect-block"><h3>已载入归属 / 修订</h3><p id="loaded-context" role="status">尚未载入记录</p></section><section class="inspect-block"><h3>来源声明 · 不构成原件核验</h3><div id="source"></div></section><section class="inspect-block"><h3>待核对步骤 · 非完成进度</h3><ol class="steps"><li>核对同案登记回执与来源声明</li><li>逐行修改，并说明修改依据</li><li>保存后核对反馈，再按运行重开</li></ol></section><p class="notice">不提供原图、下载或模型任务。文字核对不等于事实确认；有本实验记录的案件仍不支持整案归档。请求使用服务器会话与逐案授权；会话、权限与隔离运行待真实验收。</p></aside></div><script src='+scripts.replace('</html>','</body></html>'))
